import{b as d,O as e,g as a,j as o}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"附录B · 常见错误码及解决方案","description":"","frontmatter":{},"headers":[],"relativePath":"database/oracle/appendix/error-codes/index.md","filePath":"数据库管理/Oracle从入门到精通/附录/B.常见错误码.md","lastUpdated":1782140566000}'),r={name:"database/oracle/appendix/error-codes/index.md"};function c(h,t,n,i,l,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="附录b-·-常见错误码及解决方案" tabindex="-1">附录B · 常见错误码及解决方案 <a class="header-anchor" href="#附录b-·-常见错误码及解决方案" aria-label="Permalink to &quot;附录B · 常见错误码及解决方案&quot;">​</a></h1><h2 id="连接与实例" tabindex="-1">连接与实例 <a class="header-anchor" href="#连接与实例" aria-label="Permalink to &quot;连接与实例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-12541</code></td><td>TNS:no listener</td><td>监听器未启动</td><td><code>lsnrctl start</code></td></tr><tr><td><code>ORA-12170</code></td><td>TNS:Connect timeout</td><td>网络不通或防火墙拦截</td><td>检查网络、防火墙、1521 端口</td></tr><tr><td><code>ORA-01034</code></td><td>ORACLE not available</td><td>实例未启动</td><td><code>STARTUP</code></td></tr><tr><td><code>ORA-01033</code></td><td>ORACLE initialization or shutdown in progress</td><td>数据库正在启动或关闭中</td><td>等待操作完成</td></tr></tbody></table><h2 id="sql-语法与对象" tabindex="-1">SQL 语法与对象 <a class="header-anchor" href="#sql-语法与对象" aria-label="Permalink to &quot;SQL 语法与对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-00942</code></td><td>table or view does not exist</td><td>表或视图不存在，或无权限</td><td>检查表名拼写、确认有 SELECT 权限</td></tr><tr><td><code>ORA-00904</code></td><td>invalid identifier</td><td>列名不存在或拼写错误</td><td><code>DESC 表名</code> 确认列名</td></tr><tr><td><code>ORA-00933</code></td><td>SQL command not properly ended</td><td>SQL 语句结尾不正确</td><td>检查分号、多余的关键字</td></tr><tr><td><code>ORA-01722</code></td><td>invalid number</td><td>字符串无法转为数字</td><td>检查数据中是否有非数字字符</td></tr><tr><td><code>ORA-01400</code></td><td>cannot insert NULL</td><td>非空约束列插入了 NULL</td><td>给 NOT NULL 列提供值</td></tr><tr><td><code>ORA-00001</code></td><td>unique constraint violated</td><td>主键或唯一约束冲突</td><td>检查是否插入重复值</td></tr><tr><td><code>ORA-02291</code></td><td>integrity constraint violated - parent key not found</td><td>外键引用的父表键不存在</td><td>先插入父表数据，再插入子表</td></tr><tr><td><code>ORA-02292</code></td><td>integrity constraint violated - child record found</td><td>有子表记录引用，无法删除父表</td><td>先删除或修改子表数据</td></tr><tr><td><code>ORA-00955</code></td><td>name is already used by an existing object</td><td>对象名已存在</td><td>改名或 DROP 旧对象</td></tr></tbody></table><h2 id="pl-sql-与触发器" tabindex="-1">PL/SQL 与触发器 <a class="header-anchor" href="#pl-sql-与触发器" aria-label="Permalink to &quot;PL/SQL 与触发器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-01403</code></td><td>no data found</td><td>SELECT INTO 没有查到数据</td><td>用异常处理 <code>NO_DATA_FOUND</code></td></tr><tr><td><code>ORA-01422</code></td><td>exact fetch returns more than requested number of rows</td><td>SELECT INTO 返回了多行</td><td>改用游标或加 ROWNUM 限制</td></tr><tr><td><code>ORA-06550</code></td><td>PLS-00103: Encountered the symbol ...</td><td>PL/SQL 语法错误</td><td>检查拼写、分号、END 匹配</td></tr><tr><td><code>ORA-04098</code></td><td>trigger is invalid</td><td>触发器编译失败</td><td><code>SHOW ERRORS</code> 查看详细错误</td></tr><tr><td><code>ORA-04091</code></td><td>table is mutating</td><td>行级触发器查询或修改了自身表</td><td>改用语句级触发器或复合触发器</td></tr></tbody></table><h2 id="并发与锁" tabindex="-1">并发与锁 <a class="header-anchor" href="#并发与锁" aria-label="Permalink to &quot;并发与锁&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-00054</code></td><td>resource busy and acquire with NOWAIT</td><td>对象被锁定</td><td>等待或 <code>ALTER SYSTEM KILL SESSION</code></td></tr><tr><td><code>ORA-00060</code></td><td>deadlock detected</td><td>死锁</td><td>Oracle 自动牺牲一个会话，应用应捕获并重试</td></tr><tr><td><code>ORA-08177</code></td><td>can&#39;t serialize access</td><td>SERIALIZABLE 事务写冲突</td><td>降低隔离级别或重试事务</td></tr></tbody></table><h2 id="空间与存储" tabindex="-1">空间与存储 <a class="header-anchor" href="#空间与存储" aria-label="Permalink to &quot;空间与存储&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-01555</code></td><td>snapshot too old</td><td>Undo 空间不足，旧版本被覆盖</td><td>增大 Undo 表空间、延长 UNDO_RETENTION、优化查询</td></tr><tr><td><code>ORA-01653</code></td><td>unable to extend table by ... in tablespace</td><td>表空间满了</td><td>扩展数据文件或增加新的数据文件</td></tr><tr><td><code>ORA-01536</code></td><td>space quota exceeded for tablespace</td><td>用户配额用完</td><td>增加用户 QUOTA</td></tr></tbody></table><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-01031</code></td><td>insufficient privileges</td><td>权限不足</td><td>授予相应权限</td></tr><tr><td><code>ORA-01940</code></td><td>cannot drop a user that is currently connected</td><td>用户有活跃连接</td><td>先断开会话再删用户</td></tr></tbody></table><h2 id="data-pump" tabindex="-1">Data Pump <a class="header-anchor" href="#data-pump" aria-label="Permalink to &quot;Data Pump&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误码</th><th>信息</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>ORA-39001</code></td><td>invalid argument value</td><td>Data Pump 参数错误</td><td>检查参数拼写和值</td></tr><tr><td><code>ORA-39002</code></td><td>invalid operation</td><td>操作不合法</td><td>检查操作和参数的组合</td></tr><tr><td><code>ORA-39168</code></td><td>object not found during import</td><td>导入的对象不存在</td><td>确认导出时包含了该对象</td></tr></tbody></table>',15)])])}const O=d(r,[["render",c]]);export{u as __pageData,O as default};
